:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #e0e0e0;
  --correct: #4caf50;
  --wrong: #f44336;
  --accent: #ffb74d;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 600;
  text-align: center;
  color: var(--accent);
}

.subtitle {
  text-align: center;
  font-size: 1rem;
  opacity: 0.85;
}

.target {
  font-family: 'Courier New', monospace;
  font-size: 1.25rem;
  line-height: 1.5;
  background: rgba(0,0,0,0.25);
  padding: 16px;
  border-radius: 8px;
  word-break: break-word;
  min-height: 3.5rem;
}

.target span.correct {
  color: var(--correct);
}

.target span.wrong {
  color: var(--wrong);
  text-decoration: underline wavy var(--wrong);
}

input {
  font-family: 'Courier New', monospace;
  font-size: 1.125rem;
  padding: 12px 16px;
  border: 2px solid #555;
  border-radius: 8px;
  background: #1a1a2e;
  color: var(--text);
  width: 100%;
  outline: none;
  transition: border-color 0.2s;
}

input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 183, 77, 0.3);
}

.hint {
  font-size: 0.875rem;
  opacity: 0.7;
}

.result {
  font-size: 1.25rem;
  font-weight: 600;
  text-align: center;
  padding: 8px;
  background: rgba(255, 183, 77, 0.1);
  border-radius: 8px;
}

.result span {
  color: var(--accent);
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #1e1e2f;
  cursor: pointer;
  align-self: center;
  transition: background 0.2s, transform 0.1s;
}

button:hover {
  background: #ffa726;
}

button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .target {
    font-size: 1.125rem;
  }
}

const targetEl = document.getElementById('target');
const inputEl = document.getElementById('input');
const resultEl = document.getElementById('result');
const accuracyEl = document.getElementById('accuracy');
const restartBtn = document.getElementById('restart');

const SENTENCE = 'The quick brown fox jumps over the lazy dog.';
let finished = false;

function renderTarget(typed) {
  let html = '';
  for (let i = 0; i < SENTENCE.length; i++) {
    const ch = SENTENCE[i];
    const cls = i < typed.length ? (typed[i] === ch ? 'correct' : 'wrong') : '';
    html += cls ? `<span class="${cls}">${ch}</span>` : ch;
  }
  targetEl.innerHTML = html;
}

function calculateAccuracy(typed) {
  let correct = 0;
  for (let i = 0; i < typed.length; i++) {
    if (typed[i] === SENTENCE[i]) correct++;
  }
  return Math.round((correct / SENTENCE.length) * 100);
}

function handleInput() {
  if (finished) return;
  const typed = inputEl.value;
  renderTarget(typed);
  if (typed.length >= SENTENCE.length) {
    finished = true;
    inputEl.disabled = true;
    const acc = calculateAccuracy(typed);
    accuracyEl.textContent = acc;
    resultEl.hidden = false;
  }
}

function restart() {
  finished = false;
  inputEl.disabled = false;
  inputEl.value = '';
  resultEl.hidden = true;
  accuracyEl.textContent = '0';
  renderTarget('');
  inputEl.focus();
}

inputEl.addEventListener('input', handleInput);
restartBtn.addEventListener('click', restart);

// Initialize
renderTarget('');
inputEl.focus();
